// Reference: CreateOwner pattern
using Smartlog.Domain.Entities.MasterData;

namespace Smartlog.Application.Features.MasterData.Owners.Commands;

public class CreateOwner
{
    public record Command(
        string StorerKey,
        string Name,
        string? OwnerType,
        bool DualTrackingEnabled,
        string? ContactPerson,
        string? ContactEmail,
        string? ContactPhone,
        bool IsActive = true
    ) : ICommand<Guid>;

    public class CommandValidator : AbstractValidator<Command>
    {
        public CommandValidator(ILocalizationService localizationService)
        {
            RuleFor(x => x.StorerKey)
                .NotEmpty().WithName(localizationService.GetPropertyName("Owner.StorerKey"))
                .MaximumLength(OwnerConsts.ColumnMaxLengths.StorerKey)
                    .WithName(localizationService.GetPropertyName("Owner.StorerKey"));
        }
    }

    public class CommandHandler(
        IAppDbContext context,
        ILogger<CommandHandler> logger) : ICommandHandler<Command, Guid>
    {
        public async Task<Guid> HandleAsync(Command command, CancellationToken cancellationToken = default)
        {
            if (await context.Owners.AnyAsync(x => x.StorerKey.ToLower() == command.StorerKey.ToLower(), cancellationToken))
                throw BusinessRule.Owners.StorerKeyAlreadyExists.ToBusinessException([command.StorerKey]);

            var entity = new Owner { StorerKey = command.StorerKey, Name = command.Name /* ... */ };
            context.Owners.Add(entity);
            await context.SaveChangesAsync(cancellationToken);
            return entity.Id;
        }
    }
}

