// Reference: GetOwnerList (DynamicGrid) + GetOwnerById
namespace Smartlog.Application.Features.MasterData.Owners.Queries;

public class GetOwnerList
{
    public record Query : DynamicListQuery, IDynamicGridQuery, IQuery<DynamicGridResult>
    {
        public string FormCode { get; init; } = "MDTOWNG01";
        public string? SearchFormCode { get; init; } = "MDTOWNS01";
        public Dictionary<string, object?>? FilterValues { get; init; }
    }

    public class QueryHandler(IServiceProvider serviceProvider, ICurrentUser currentUser)
        : DynamicGridQueryHandler<Query>(serviceProvider), IQueryHandler<Query, DynamicGridResult>
    {
        protected override string GetConfigName() => "Owners";
        protected override Guid? UserId() => currentUser?.UserId;
    }
}

public class GetOwnerById
{
    public record Query(Guid Id) : IQuery<OwnerDto?>;
    public class QueryHandler(IAppDbContext context) : IQueryHandler<Query, OwnerDto?>
    {
        public async Task<OwnerDto?> HandleAsync(Query query, CancellationToken ct = default)
        {
            var entity = await context.Owners.AsNoTracking().FirstOrDefaultAsync(x => x.Id == query.Id, ct);
            return entity?.ToDto();
        }
    }
}

