// Reference: OwnersController
[ApiController]
[Route("api/owners")]
[Authorize]
public sealed class OwnersController(IDispatcher dispatcher) : ControllerBase
{
    [HttpGet("lookup")]
    public async Task<IActionResult> Lookup([FromQuery] string? search, [FromQuery] int? limit, CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(new GetOwnerLookup.Query { Search = search, Limit = limit }, ct);
        return Ok(ApiResult<List<LookupDto>>.Success(result));
    }

    [HttpGet]
    public async Task<IActionResult> GetList([FromQuery] int page = 1, [FromQuery] int pageSize = 10,
        [FromQuery] string? filter = null, [FromQuery] string? sort = null,
        [FromQuery] string? formCode = "MDTOWNG01", CancellationToken ct = default)
    {
        var query = new GetOwnerList.Query { Page = page, PageSize = pageSize, Filter = filter, Sort = sort, FormCode = formCode ?? "MDTOWNG01" };
        return Ok(ApiResult<DynamicGridResult>.Success(await dispatcher.QueryAsync(query, ct)));
    }

    [HttpPost("search")]
    public async Task<IActionResult> Search([FromBody] GetOwnerList.Query query, CancellationToken ct)
        => Ok(ApiResult<DynamicGridResult>.Success(await dispatcher.QueryAsync(query, ct)));

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id, CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(new GetOwnerById.Query(id), ct);
        return result == null ? NotFound() : Ok(ApiResult<OwnerDto>.Success(result));
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateOwner.Command command, CancellationToken ct)
        => StatusCode(201, ApiResult<Guid>.Success(await dispatcher.DispatchAsync(command, ct)));

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] UpdateOwner.Command command, CancellationToken ct)
    { await dispatcher.DispatchAsync(command with { Id = id }, ct); return NoContent(); }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    { await dispatcher.DispatchAsync(new DeleteOwner.Command(id), ct); return NoContent(); }
}

