// Reference: weighbridges API
import { apiClient } from '@/lib/api-client'

export const weighbridgesApi = {
    getWeighbridges: async (params: SearchParams) => {
        const response = await apiClient.post('/weighbridges/search', {
            ...params,
            formCode: params.formCode || 'OPSWBDG01',
            searchFormCode: params.searchFormCode || 'OPSWBDS01',
            filterValues: params.filterValues || {},
        })
        return response.data.data
    },
    getWeighbridge: async (id: string) => {
        const response = await apiClient.get(`/weighbridges/${id}`)
        return response.data.data
    },
    createWeighbridge: async (data: CreateWeighbridgeCommand) => {
        const response = await apiClient.post('/weighbridges', data)
        return response.data.data
    },
    updateWeighbridge: async (id: string, data: UpdateWeighbridgeCommand) => {
        const response = await apiClient.put(`/weighbridges/${id}`, data)
        return response.data.data
    },
    deleteWeighbridge: async (id: string) => { await apiClient.delete(`/weighbridges/${id}`) },
    getWeighbridgeLookup: async (params?: { search?: string }) => {
        const response = await apiClient.get('/weighbridges/lookup', { params })
        return response.data.data
    },
}

