// Reference: weighbridges-dialogs.tsx
import { FeatureDialogManager } from '@/components/feature-dialog-manager'
import { useWeighbridges } from './use-weighbridges'
import { weighbridgesApi } from '../api/weighbridges'
import { weighbridgesInputFields, createWeighbridgesInputSchema, weighbridgesDefaultValues } from '../config/weighbridges-input.config'
import { useTranslation } from 'react-i18next'
import { viewDataKeys } from '@/core/api/query-keys'

export function WeighbridgesDialogs() {
    const { t } = useTranslation('weighbridges')
    const inputSchema = createWeighbridgesInputSchema()
    const { open, setOpen, currentRow, setCurrentRow } = useWeighbridges()
    return (
        <FeatureDialogManager
            open={open} onOpenChange={(val) => setOpen(val as 'add' | 'edit')}
            currentRow={currentRow} onRowChange={setCurrentRow}
            formConfig={weighbridgesInputFields} formSchema={inputSchema}
            formDefaultValues={weighbridgesDefaultValues}
            createMutationFn={weighbridgesApi.createWeighbridge}
            updateMutationFn={(id, data) => weighbridgesApi.updateWeighbridge(id, data)}
            queryKey={viewDataKeys.listsBySource('weighbridges')}
            entityName={t('entityName')} maxWidth='md' gridCols={2}
        />
    )
}
